#!/usr/bin/env node
// Generated by Keel — byte budgets + split-doc integrity. Copy to .keel/doc-size.mjs (every upgrade).
// Usage: node .keel/doc-size.mjs [--json] [--after-archive]   check (read-only)
//        node .keel/doc-size.mjs --split <doc.md>             split one oversize doc or part (writes files)
//        node .keel/doc-size.mjs --where <doc.md> "<section>"   print the file that holds <section>
//        node .keel/doc-size.mjs --move-out <AGENTS.md|CLAUDE.md> "<## section>"   keystone → docs/agents/
//        node .keel/doc-size.mjs --self-test
// One VERDICT per doc, with the reason:
//   ok      within budget; or an archive (append-only history) or a redirect stub — never budgeted, never split
//   waived  over budget, but .keel/meta.json "waivers" records why (reason + reviewed date)
//   archive move closed detail out first (keystone: then --move-out whole sections, linked)
//   split   split into <dir>/<name>/NN-<slug>.md behind the parent index (--split does it, recursively)
//   manual  over budget and no safe automatic fix (generated file, index too big, nothing to cut at)
// Measured once each: AGENTS.md, CLAUDE.md, root CHANGELOG/COMMANDS/RUNBOOK.md, every docs/**.md that
// is not inside a split folder or the ADR directory, every "budgets"/"waivers" key, and every part.
// A SPLIT doc is any NAME.md with a "## Parts" heading AND a sibling folder name/ (nested too:
// docs/adr/README.md → docs/adr/readme/). A redirect stub ("# X → moved") and the per-file ADR
// directory are never split parents. Budget = budgets[path] ?? defaultBudget ?? 32768; the ADR index
// grows 320 B per ADR (a budgets entry is a floor; the checker says when the ADR count overrides it). Exit 1 only on link errors (part not linked from parent / no link back).
// Links count inline, reference-style, file-relative and repo-absolute (/docs/x.md).
// ADR files are immutable: --split never rewrites them; anchors they cite stay findable via the
// index's "Moved sections" list.
import { readdirSync, readFileSync, statSync, existsSync, writeFileSync, mkdirSync, mkdtempSync } from 'fs'
import { join, posix } from 'path'
import { tmpdir } from 'os'

const { dirname, basename, relative } = posix
const KEYSTONE = new Set(['AGENTS.md', 'CLAUDE.md'])
const ROOT_DOCS = ['AGENTS.md', 'CLAUDE.md', 'CHANGELOG.md', 'COMMANDS.md', 'RUNBOOK.md']
const ARCHIVABLE = new Set(['docs/IMPLEMENTATION_PLAN.md', 'CHANGELOG.md', 'docs/CHANGELOG.md',
  'RUNBOOK.md', 'docs/RUNBOOK.md', 'docs/DEPLOYMENT.md'])
const ADR_ROW = 320
const ADR_FILE = /(^|\/)adr\/ADR-[^/]+\.md$/i
const PART_OF = /^> Part of \[[^\]]+\]\(((?:\.\.\/)+[^)#]+\.md)\)/m
const kebab = f => basename(f, '.md').toLowerCase().replace(/_/g, '-')
const folderOf = f => KEYSTONE.has(f) ? `docs/${kebab(f)}` : posix.join(dirname(f), kebab(f))
const isArchive = (f, meta) => /ARCHIVE/i.test(basename(f)) || /^LEGACY_/i.test(basename(f)) ||
  /(^|\/)archive\//i.test(f) || (meta.archives || []).includes(f)
const isStub = text => /^# [^\n]*(→|->)\s*moved\b/im.test(text.slice(0, 300))
const isGenerated = text => /^(<!--[^\n]*)?[^\n]*\b(auto-?generated|do not edit|generated by (?!keel))/im.test(text.slice(0, 400))
const hasParts = text => /^## Parts\s*$/m.test(text)
const isDir = (root, d) => existsSync(join(root, d)) && statSync(join(root, d)).isDirectory()
const read = (root, f) => readFileSync(join(root, f), 'utf8')
const bytes = s => Buffer.byteLength(s)
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
const day = 864e5
// GitHub heading anchor: lowercase, drop punctuation (keep word chars, "-", space), each space → "-"
const slug = t => t.toLowerCase().replace(/[`*[\]()]/g, '').replace(/[^\p{L}\p{N}_\s-]/gu, '').trim().replace(/\s/g, '-')
const loadMeta = root => { try { return JSON.parse(read(root, '.keel/meta.json')) } catch { return {} } }
const walk = (root, d) => !isDir(root, d) ? [] : readdirSync(join(root, d), { withFileTypes: true }).flatMap(e =>
  e.name.startsWith('.') || e.name === 'node_modules' ? [] : e.isDirectory() ? walk(root, posix.join(d, e.name)) : e.name.endsWith('.md') ? [posix.join(d, e.name)] : [])

// Every link target in a markdown file, as a repo-relative path (anchors and titles dropped).
export function linkTargets(text, from) {
  const raw = [...text.matchAll(/\]\(\s*<?([^)\s>]+)>?(?:\s+["'(][^)]*)?\)/g),
    ...text.matchAll(/^ {0,3}\[[^\]]+\]:\s*<?(\S+?)>?(?:\s+.*)?$/gm)].map(m => m[1])
  const out = new Set()
  for (let t of raw) {
    t = t.split('#')[0]
    if (!t || /^[a-z][\w+.-]*:/i.test(t)) continue
    out.add(t.startsWith('/') ? posix.normalize(t.slice(1)) : posix.join(dirname(from), t))
  }
  return out
}

// ── Cutting ─────────────────────────────────────────────────────────────────────────────────
function sections(text, level) {
  const mark = '#'.repeat(level) + ' '
  const out = [{ title: null, text: '' }]
  let fence = false
  for (const line of text.split(/(?<=\n)/)) {
    if (/^\s*(```|~~~)/.test(line)) fence = !fence
    if (!fence && line.startsWith(mark)) out.push({ title: line.slice(mark.length).trim(), text: '' })
    out[out.length - 1].text += line
  }
  return out
}
// The biggest markdown table outside fences: {start, end, header, rows, title of nearest heading above}
function bigTable(text) {
  const lines = text.split(/(?<=\n)/)
  let best = null, fence = false, title = null
  for (let i = 0; i < lines.length; i++) {
    if (/^\s*(```|~~~)/.test(lines[i])) fence = !fence
    if (!fence && /^#{1,6} /.test(lines[i])) title = lines[i].replace(/^#+ /, '').trim()
    if (fence || title === 'Parts' || title === 'Moved sections' || !/^\|/.test(lines[i]) || !/^\|[\s:|-]+\|\s*$/.test(lines[i + 1] || '')) continue
    let j = i + 2
    while (j < lines.length && /^\|/.test(lines[j])) j++
    const t = { start: i, end: j, header: lines[i] + lines[i + 1], rows: lines.slice(i + 2, j), title, lines }
    if (t.rows.length >= 2 && (!best || bytes(t.rows.join('')) > bytes(best.rows.join('')))) best = t
    i = j - 1
  }
  return best
}
// How to cut: sections at the shallowest level giving enough pieces, else a big table by rows.
function plan(text, isPart) {
  for (let lvl = 2; lvl <= 6; lvl++) {
    const [head, ...all] = sections(text, lvl)
    const partsSec = lvl === 2 ? all.find(s => s.title === 'Parts') : null
    const secs = all.filter(s => s !== partsSec)
    if (secs.length >= (isPart ? 2 : 1)) return { kind: 'sections', head, secs, partsSec }
  }
  const t = bigTable(text)
  if (t) return { kind: 'rows', table: t }
  return null
}
const MIN_PART = 2048
function group(secs, budget) {
  const groups = []
  for (const sec of secs) {
    const last = groups[groups.length - 1]
    if (last && bytes(last.text) < MIN_PART && bytes(last.text + sec.text) <= budget) {
      last.text += sec.text; last.titles.push(sec.title)
    } else groups.push({ titles: [sec.title], text: sec.text })
  }
  return groups
}

export function check(root, { afterArchive = false, now = Date.now() } = {}) {
  const meta = loadMeta(root)
  const budgets = meta.budgets || {}
  const def = meta.defaultBudget || 32768
  // waivers {path: {reason, reviewed, max?}}; legacy budgetExceptions {path: "reason"} read as unreviewed waivers
  const waivers = { ...Object.fromEntries(Object.entries(meta.budgetExceptions || {}).map(([f, r]) =>
    [f, { reason: String(r), reviewed: null, legacy: true }])), ...(meta.waivers || {}) }
  const reviewDays = meta.waiverReviewDays || 90
  const exists = f => existsSync(join(root, f)) && statSync(join(root, f)).isFile()
  const adrDir = meta.adrDir || 'docs/adr'
  const adrCount = walk(root, adrDir).filter(f => ADR_FILE.test(f)).length
  // split parents anywhere under docs/ (nested too) + root docs; never the ADR directory itself
  const all = [...ROOT_DOCS.filter(exists), ...walk(root, 'docs')]
  const parents = all.filter(f => { const fo = folderOf(f); const t = read(root, f)
    return fo !== adrDir && !isStub(t) && hasParts(t) && isDir(root, fo) })
  const inFolder = new Set(parents.flatMap(p => walk(root, folderOf(p))))
  const docs = [...new Set([...all.filter(f => !inFolder.has(f) && !ADR_FILE.test(f)),
  ...Object.keys(budgets), ...Object.keys(waivers)])].filter(exists)
  const files = [], linkErrors = [], families = [], seen = new Set()

  const judge = (f, budget, part) => {
    if (seen.has(f)) return 0
    seen.add(f)
    const text = read(root, f), size = bytes(text)
    const isAdrIndex = f === `${adrDir}/README.md`
    // ADR index budget = max(budgets entry, 320 B × ADRs): the entry is a floor; say when the ADR count overrides it
    const stale = isAdrIndex && budgets[f] != null && budgets[f] < adrCount * ADR_ROW
      ? ` (overrides budgets["${f}"] = ${budgets[f]} B, which is only a floor)` : ''
    if (isAdrIndex) budget = Math.max(budget, adrCount * ADR_ROW)
    const r = { file: f, size, budget, part: part || null }
    const w = waivers[f]
    if (isArchive(f, meta) || (part && isArchive(part, meta))) Object.assign(r, { verdict: 'ok', reason: 'archive: append-only history, not budgeted, never split' })
    else if (isStub(text)) Object.assign(r, { verdict: 'ok', reason: 'redirect stub: never split, never a split parent' })
    else if (size <= budget) {
      const left = budget - size
      Object.assign(r, { verdict: 'ok', reason: isAdrIndex && adrCount ? `ADR index, budget ${ADR_ROW} B × ${adrCount} ADRs${stale}` :
        left < Math.max(256, budget * 0.02) ? `tight: ${left} B left — move content out before adding` : '' })
    } else if (w && !(w.max && size > w.max)) {
      const due = !w.reviewed || now - Date.parse(w.reviewed) > reviewDays * day
      Object.assign(r, { verdict: 'waived', reason: `${w.reason}${due ? ` — review due${w.legacy ? ' (legacy budgetExceptions entry: move to "waivers" with a reviewed date)' : ''}` : ` (reviewed ${w.reviewed})`}` })
    } else if (KEYSTONE.has(f)) Object.assign(r, { verdict: 'archive', reason: `keystone, never split: archive closed detail, then move whole sections out (node .keel/doc-size.mjs --move-out ${f} "<section>") — do not compress wording` })
    else if (isGenerated(text)) Object.assign(r, { verdict: 'manual', reason: 'generated file: shrink its generator or add a waiver — a split would be overwritten' })
    else if (isAdrIndex) Object.assign(r, { verdict: 'manual', reason: `ADR index over ${ADR_ROW} B per ADR: shorten row titles or add a waiver — never split an index${stale}` })
    else if (ARCHIVABLE.has(f) && !afterArchive) Object.assign(r, { verdict: 'archive', reason:
      (f.endsWith('IMPLEMENTATION_PLAN.md') ? 'move done phases to PHASE_ARCHIVE; if open deferred rows dominate run /keel closeout' : 'move closed entries to its archive') + '; split only if still over after that' })
    else if (plan(text, !!part) && !(hasParts(text) && !part && plan(text, false)?.secs?.length === 0))
      Object.assign(r, { verdict: 'split', reason: part ? `part of ${part}: split it further (sub-parts keep its order)` : 'split into its folder behind a slim index' })
    else Object.assign(r, { verdict: 'manual', reason: hasParts(text) && !part ? 'index only, yet over budget: shorten the Parts table or add a waiver' :
      'nothing to cut at (no headings, no table with rows): add headings or split by hand' })
    if (ARCHIVABLE.has(f) && r.verdict === 'split') r.reason += ' (archive already done)'
    files.push(r)
    return size
  }

  for (const doc of docs) {
    const budget = budgets[doc] ?? def
    let total = judge(doc, budget)
    if (!parents.includes(doc)) continue
    const folder = folderOf(doc), parentText = read(root, doc)
    const parts = walk(root, folder).sort()
    const fromParent = linkTargets(parentText, doc)
    for (const rel of parts) {
      total += judge(rel, KEYSTONE.has(doc) ? def : budget, doc)
      if (!fromParent.has(rel)) linkErrors.push(`${rel}: not linked from ${doc}`)
      if (!linkTargets(read(root, rel), rel).has(doc)) linkErrors.push(`${rel}: no link back to ${doc}`)
    }
    families.push({ parent: doc, folder, parts: parts.length, total })
  }
  const breaches = files.filter(f => ['archive', 'split', 'manual'].includes(f.verdict)).map(f => ({ ...f, action: f.verdict }))
  return { ok: linkErrors.length === 0, files, breaches, linkErrors, families }
}

// Which file holds <section> of <doc>: the doc itself, or (split doc) the LAST part whose headings
// mention it (row-split tables continue in the last part). Writers (phase/change/closeout, doc-sync)
// call this instead of assuming the section is in the parent.
export function where(root, doc, section) {
  const folder = folderOf(doc)
  if (!hasParts(read(root, doc)) || !isDir(root, folder)) return doc
  const re = new RegExp(`^#{1,6} .*${esc(section)}`, 'im')
  const hits = walk(root, folder).sort().filter(p => re.test(read(root, p)))
  return hits.length ? hits[hits.length - 1] : doc
}

// ── Split ───────────────────────────────────────────────────────────────────────────────────
// Deterministic split per keel-archive-guide "Splitting an oversize doc". Moves text verbatim.
// Plain doc → its "## " sections go to <name>/NN-<slug>.md (small neighbours merged); the parent
// keeps H1 + intro and its "## Parts" table (created or appended — a re-run moves only what is new).
// A part keeps its first chunk; the rest go to sub-parts named after it (07 → 07a, 07b; 07a → 07aa),
// so file order = section order, listed right after it in the Parts table. Cut level: the shallowest
// heading level with enough sections (## … ######), else the biggest table by rows (header repeated).
// Recursive: any new part — or the kept part — still over budget is cut again in the same run.
// Inbound NAME.md#anchor links — markdown links and backticked `path#anchor` — are repointed
// everywhere except ADR files (immutable); the index lists every moved anchor under "Moved sections".
export function split(root, doc, budget, depth = 0) {
  const text = read(root, doc)
  const pm = text.match(PART_OF)
  const isPart = !!pm
  const parentRel = isPart ? posix.join(dirname(doc), pm[1]) : doc
  const folder = folderOf(parentRel), parentBase = basename(parentRel)
  const parentText = isPart ? read(root, parentRel) : text
  const docTitle = (parentText.match(/^# (.+)$/m) || [, basename(parentRel, '.md')])[1].trim()
  const backLink = relative(folder, parentRel)
  const p = plan(text, isPart)
  if (!p || (p.kind === 'sections' && !isPart && !p.secs.length))
    throw new Error(`${doc}: nothing to split — no sections or table rows${hasParts(text) ? ' outside the Parts index (already split)' : ''}`)

  let keep = null, pieces = []          // pieces: {title, covers, text}
  if (p.kind === 'sections') {
    let groups = group(p.secs, budget)
    if (isPart) { keep = p.head.text + groups[0].text; groups = groups.slice(1) }
    pieces = groups.map(g => ({ title: g.titles[0], covers: g.titles.join(', '), text: g.text }))
  } else {
    const t = p.table, room = Math.max(MIN_PART, budget - bytes(t.header) - 512)
    const chunks = [[]]
    for (const row of t.rows) {
      const c = chunks[chunks.length - 1]
      if (c.length && bytes(c.join('') + row) > room) chunks.push([])
      chunks[chunks.length - 1].push(row)
    }
    if (chunks.length < 2) throw new Error(`${doc}: one table row block only — nothing to cut`)
    keep = t.lines.slice(0, t.start).join('') + t.header + chunks[0].join('') + t.lines.slice(t.end).join('')
    let n = chunks[0].length
    pieces = chunks.slice(1).map(c => { const from = n + 1; n += c.length
      return { title: `${t.title || 'Table'} (rows ${from}-${n})`, covers: `${t.title || 'table'} rows ${from}-${n}`, text: t.header + c.join('') } })
  }
  if (!pieces.length) throw new Error(`${doc}: one section only — nothing to cut`)

  mkdirSync(join(root, folder), { recursive: true })
  const existing = readdirSync(join(root, folder))
  const myPrefix = isPart ? (basename(doc).match(/^(\d+[a-z]*)-/) || [])[1] : null
  const letters = 'abcdefghijklmnopqrstuvwxyz'
  let nn = Math.max(0, ...existing.map(f => parseInt(f, 10) || 0)) + 1, li = 0
  const nextName = s => {
    if (!myPrefix) return `${String(nn++).padStart(2, '0')}-${s}`
    // ponytail: 26 sub-parts per level; a 27th goes one level deeper (…zz) — still sorts in order
    for (;;) { const pre = myPrefix + (li < 26 ? letters[li] : 'z' + letters[li - 26] ); li++
      if (!existing.some(f => f.startsWith(pre + '-'))) return `${pre}-${s}` }
  }
  const made = [], moved = {}
  for (const g of pieces) {
    const name = `${nextName(slug(g.title).slice(0, 40) || 'part')}.md`
    const body = g.text.replace(/^\n+/, '')
    const head = /^#{1,6} /.test(body) ? '' : `\n`
    writeFileSync(join(root, folder, name),
      `# ${docTitle} — ${g.title}\n> Part of [${parentBase}](${backLink}) · all parts listed there.\n${head}\n${body}`)
    made.push({ path: posix.join(folder, name), covers: g.covers })
    for (const m of g.text.matchAll(/^#{2,6} (.+)$/gm)) moved[slug(m[1])] = posix.join(folder, name)
  }
  const rowOf = m => `| [${basename(m.path, '.md')}](${relative(dirname(parentRel), m.path)}) | ${m.covers} |\n`
  const addRows = (pt, after) => {
    const rows = made.map(rowOf).join('')
    if (after) {               // insert right after the last row of this part's family (keeps order)
      const lines = pt.split(/(?<=\n)/)
      const re = new RegExp(`\\]\\(${esc(basename(folder))}/${after}[a-z]*-[^)#]*\\.md\\)`)
      const idx = lines.map((l, i) => re.test(l) ? i : -1).filter(i => i >= 0).pop()
      if (idx !== undefined) { lines.splice(idx + 1, 0, rows); return lines.join('') }
    }
    const tbl = pt.match(/## Parts\n[\s\S]*?\n\|[^\n]*\|\n(?![|])/)
    return tbl ? pt.replace(tbl[0], tbl[0] + rows) : pt.trimEnd() + `\n\n## Parts\n\n| Part | Covers |\n|---|---|\n${rows}`
  }
  if (isPart) {
    writeFileSync(join(root, doc), keep)
    writeFileSync(join(root, parentRel), addRows(parentText, myPrefix))
  } else if (p.kind === 'sections' && p.partsSec) {
    writeFileSync(join(root, doc), addRows(`${p.head.text.trimEnd()}\n\n${p.partsSec.text}`))
  } else if (p.kind === 'rows') {
    writeFileSync(join(root, doc), addRows(keep))
  } else {
    writeFileSync(join(root, doc), `${p.head.text.trimEnd()}\n\n## Parts\n\nSplit ${new Date().toISOString().slice(0, 10)} at ${bytes(text)} B > ${budget} B. Every part links back here.\n\n| Part | Covers |\n|---|---|\n` + made.map(rowOf).join(''))
  }

  // repoint inbound anchored references to the moved headings; ADR files are immutable — skipped
  let rewired = 0, adrSkipped = 0
  const targets = new Set([parentRel, doc])
  for (const f of walk(root, '.').map(x => x.replace(/^\.\//, ''))) {
    const src = read(root, f)
    const fix = (all, open, target, anchor, close) => {
      const fileRel = posix.join(dirname(f), target), rootRel = posix.normalize(target.replace(/^\//, ''))
      const hit = targets.has(fileRel) ? 'file' : targets.has(rootRel) ? 'root' : null
      const to = hit && moved[anchor]
      if (!to) return all
      if (ADR_FILE.test(f)) { adrSkipped++; return all }
      rewired++
      return `${open}${hit === 'file' ? relative(dirname(f), to) : to}#${anchor}${close}`
    }
    const out = src.replace(/(\]\()([^)\s#]+?)#([^)\s]+)(\))/g, fix).replace(/(`)([^`\s#]+?\.md)#([^`\s]+)(`)/g, fix)
    if (out !== src) writeFileSync(join(root, f), out)
  }
  if (adrSkipped) {          // anchors ADRs still cite: list them on the index so a reader finds the part
    const pt = read(root, parentRel)
    const rows = Object.entries(moved).filter(([a]) => !pt.includes(`| \`#${a}\` |`))
      .map(([a, to]) => `| \`#${a}\` | [${a}](${relative(dirname(parentRel), to)}#${a}) |\n`).join('')
    if (rows) writeFileSync(join(root, parentRel), /^## Moved sections/m.test(pt) ? pt.trimEnd() + '\n' + rows
      : pt.trimEnd() + `\n\n## Moved sections\n\nOld anchors cited by immutable ADRs → where the section lives now.\n\n| Anchor | Now in |\n|---|---|\n${rows}`)
  }

  // recurse: anything still over budget is cut again in this run
  const res = { parent: parentRel, folder, parts: made.map(m => m.path), rewired, adrSkipped }
  if (depth < 8) for (const f of [...made.map(m => m.path), ...(isPart ? [doc] : [])]) {
    if (bytes(read(root, f)) <= budget) continue
    try { const r = split(root, f, budget, depth + 1); res.parts.push(...r.parts); res.rewired += r.rewired; res.adrSkipped += r.adrSkipped } catch {}
  }
  res.parts.sort()
  return res
}

// Keystone: move one "## " section out verbatim to docs/agents/NN-<slug>.md (docs/claude/ for
// CLAUDE.md), leaving a Parts row with a "read when" pointer. Never compresses wording.
export function moveOut(root, keystone, title) {
  const text = read(root, keystone)
  const [head, ...secs] = sections(text, 2)
  const sec = secs.find(s => s.title.toLowerCase() === title.toLowerCase())
  if (!sec || sec.title === 'Parts') throw new Error(`${keystone}: no "## ${title}" section`)
  const folder = folderOf(keystone)
  mkdirSync(join(root, folder), { recursive: true })
  const nn = Math.max(0, ...readdirSync(join(root, folder)).map(f => parseInt(f, 10) || 0)) + 1
  const path = posix.join(folder, `${String(nn).padStart(2, '0')}-${slug(sec.title).slice(0, 40)}.md`)
  const title1 = (text.match(/^# (.+)$/m) || [, keystone])[1].trim()
  writeFileSync(join(root, path), `# ${title1} — ${sec.title}\n> Part of [${keystone}](${relative(folder, keystone)}) · all parts listed there.\n\n${sec.text}`)
  const row = `| [${basename(path, '.md')}](${path}) | ${sec.title} |\n`
  const rest = [head, ...secs].filter(s => s !== sec).map(s => s.text).join('')
  const tbl = rest.match(/## Parts\n[\s\S]*?\n\|[^\n]*\|\n(?![|])/)
  writeFileSync(join(root, keystone), tbl ? rest.replace(tbl[0], tbl[0] + row)
    : rest.trimEnd() + `\n\n## Parts\n\nRead a part when its row applies to your task.\n\n| Part | Covers |\n|---|---|\n${row}`)
  return path
}

if (process.argv.includes('--self-test')) {
  const fail = (what, o) => { console.log(`FAIL ${what} ` + JSON.stringify(o, null, 1)); process.exit(1) }
  const fixture = () => {
    const r = mkdtempSync(join(tmpdir(), 'keel-size-'))
    return [r, (f, s) => { mkdirSync(dirname(join(r, f)), { recursive: true }); writeFileSync(join(r, f), s) }]
  }
  const sec = (t, n, h = 2) => `${'#'.repeat(h)} ${t}\n\n${'Text about ' + t + '. '}${'lorem ipsum '.repeat(n)}\n\n${'#'.repeat(h + 1)} ${t} detail\n\nMore.\n\n`
  const verdicts = r => Object.fromEntries(check(r, { now: Date.parse('2026-10-31') }).files.map(f => [f.file, f]))

  // 1. basic verdicts + link errors
  const [r, w] = fixture()
  w('.keel/meta.json', JSON.stringify({ budgets: { 'AGENTS.md': 50 }, defaultBudget: 100 }))
  w('AGENTS.md', 'x'.repeat(60))                                   // keystone breach → archive
  w('docs/PRD.md', '## A\n' + 'y'.repeat(120))                     // → split
  w('docs/DESIGN.md', '# D\n## Parts\n[a](design/01-a.md) [b](./design/02-b.md)\n')
  w('docs/design/01-a.md', '> Part of [DESIGN.md](../DESIGN.md)\n' + 'z'.repeat(40))
  w('docs/design/02-b.md', 'no back link')                        // back-link error
  w('docs/design/03-c.md', '[up](../DESIGN.md#parts)')             // not linked from parent
  w('docs/IMPLEMENTATION_PLAN.md', '## P\n' + 'p'.repeat(101))     // → archive (then split)
  const c = check(r)
  const v = Object.fromEntries(c.files.map(b => [b.file, b.verdict]))
  if (!(!c.ok && v['AGENTS.md'] === 'archive' && v['docs/PRD.md'] === 'split' && v['docs/IMPLEMENTATION_PLAN.md'] === 'archive' &&
    check(r, { afterArchive: true }).files.find(f => f.file === 'docs/IMPLEMENTATION_PLAN.md').verdict === 'split' &&
    v['docs/design/01-a.md'] === 'ok' && c.linkErrors.length === 2 && c.linkErrors.some(e => e.startsWith('docs/design/02-b.md: no link back')) &&
    c.linkErrors.some(e => e.startsWith('docs/design/03-c.md: not linked')) && c.families[0].parts === 3 &&
    c.files.filter(f => f.file === 'docs/DESIGN.md').length === 1)) fail('check', c)

  // 2. upgrade cases from cortextOS 2.4.1 (issues 1–4, 9): clear verdict each, no false link errors, each file once
  const [q, wq] = fixture()
  const adrs = 60
  wq('.keel/meta.json', JSON.stringify({ defaultBudget: 4000, adrLayout: 'per-file', budgets: { 'AGENTS.md': 1000, 'docs/adr/README.md': 2000 },
    budgetExceptions: { 'docs/IMPLEMENTATION_PLAN.md': '55 open deferred rows; run /keel closeout' },
    waivers: { 'docs/SOC2_CONTROLS.md': { reason: 'auditor wants one file', reviewed: '2026-10-01' },
      'docs/BIG.md': { reason: 'ok up to 5000', reviewed: '2026-10-01', max: 5000 } } }))
  wq('AGENTS.md', 'k'.repeat(995))                                                  // tight keystone
  // issue 1: the ADR.md redirect stub — even WITH a Parts heading it is never a split parent
  wq('docs/ADR.md', '# ADR.md → moved\n\n## Parts\n\nSee [index](./adr/README.md) and [legacy](adr/LEGACY_ADR.md).\n')
  for (let i = 1; i <= adrs; i++) wq(`docs/adr/ADR-${String(i).padStart(3, '0')}-x.md`, '# ADR\n' + 'a'.repeat(3000))
  wq('docs/adr/README.md', '# ADRs\n## Parts\n| [01](readme/01-index.md) | index |\n' + '| [ADR-001](ADR-001-x.md) | t |\n'.repeat(adrs * 3))
  wq('docs/adr/readme/01-index.md', '# ADRs — index\n> Part of [README.md](../README.md)\n' + sec('Index', 450) + sec('Open', 450)) // issue 9: nested part, over → split
  wq('docs/adr/LEGACY_ADR.md', 'L'.repeat(50000))                                   // archive in the ADR folder
  wq('docs/PHASE_ARCHIVE.md', '# Archive\n' + sec('Phase 1', 9000))                  // archive: never split
  wq('docs/IMPLEMENTATION_PLAN.md', '# Plan\n' + sec('Deferred', 900))               // legacy exception → waived, review due
  wq('docs/SOC2_CONTROLS.md', '# SOC2\n' + sec('Controls', 900))                     // waived, reviewed
  wq('docs/BIG.md', '# Big\n' + sec('A', 300) + sec('B', 300))                       // waiver max exceeded → split
  wq('docs/GENERATED.md', '<!-- AUTO-GENERATED by scripts/gen.ts — do not edit -->\n' + sec('X', 900)) // → manual
  wq('docs/FLAT.md', 'no headings at all '.repeat(400))                              // → manual
  wq('docs/LINKS.md', '# Links\n## Parts\n\n[01]: /docs/links/01-a.md\n[a][01] and <docs/x> [b](</docs/links/02-b.md> "title")\n')
  wq('docs/links/01-a.md', '# L — A\n> Part of [LINKS.md](../LINKS.md)\nbody\n')
  wq('docs/links/02-b.md', '# L — B\nup: [parent][p]\n\n[p]: /docs/LINKS.md#parts\n')
  const k = check(q)
  const kv = verdicts(q)
  const exp = { 'AGENTS.md': 'ok', 'docs/ADR.md': 'ok', 'docs/adr/README.md': 'ok', 'docs/PHASE_ARCHIVE.md': 'ok', 'docs/adr/LEGACY_ADR.md': 'ok',
    'docs/IMPLEMENTATION_PLAN.md': 'waived', 'docs/SOC2_CONTROLS.md': 'waived', 'docs/BIG.md': 'split', 'docs/adr/readme/01-index.md': 'split',
    'docs/GENERATED.md': 'manual', 'docs/FLAT.md': 'manual', 'docs/LINKS.md': 'ok', 'docs/links/01-a.md': 'ok' }
  const bad = Object.entries(exp).filter(([f, e]) => kv[f]?.verdict !== e)
  if (bad.length || !k.ok || k.families.length !== 2 || Object.keys(kv).some(f => ADR_FILE.test(f)) ||
    !/tight/.test(kv['AGENTS.md'].reason) || !/review due.*legacy/.test(kv['docs/IMPLEMENTATION_PLAN.md'].reason) ||
    !/redirect stub/.test(kv['docs/ADR.md'].reason) || !/reviewed 2026-10-01/.test(kv['docs/SOC2_CONTROLS.md'].reason) ||
    !/320 B × 60 ADRs \(overrides budgets\["docs\/adr\/README\.md"\] = 2000 B, which is only a floor/.test(kv['docs/adr/README.md'].reason) ||
    k.files.length !== new Set(k.files.map(f => f.file)).size) fail('upgrade cases', { bad, k })
  // issue 11: keystone over budget → move whole sections out, never compress; --move-out does it
  wq('AGENTS.md', '# A\n\nIntro.\n\n## Rules\n\nkeep\n\n## Delegation\n\n' + 'd'.repeat(1100) + '\n')
  const ks = verdicts(q)['AGENTS.md']
  if (ks.verdict !== 'archive' || !/--move-out AGENTS.md.*do not compress/.test(ks.reason)) fail('keystone', ks)
  const mo = moveOut(q, 'AGENTS.md', 'Delegation')
  const kf = check(q), ag2 = read(q, 'AGENTS.md')
  if (mo !== 'docs/agents/01-delegation.md' || !kf.ok || verdicts(q)['AGENTS.md'].verdict !== 'ok' || !ag2.includes('## Rules') ||
    !ag2.includes('(docs/agents/01-delegation.md)') || !read(q, mo).includes('d'.repeat(1100)) ||
    !kf.families.some(f => f.parent === 'AGENTS.md' && f.parts === 1)) fail('move-out', { mo, kf, ag2 })

  // 3. split fixture: append to an over-limit doc → split → index + parts, links both ways, no breach.
  const [r2, w2] = fixture()
  w2('.keel/meta.json', JSON.stringify({ defaultBudget: 4000 }))
  w2('AGENTS.md', 'See [components](docs/DESIGN.md#components) and [index](docs/DESIGN.md).\n')
  w2('docs/DESIGN.md', '# DESIGN — Demo\n\nIntro line.\n\n' + sec('Foundations', 200) + sec('Components', 200) +
    '```md\n## not a heading (in a fence)\n```\n\n')
  writeFileSync(join(r2, 'docs/DESIGN.md'), read(r2, 'docs/DESIGN.md') + sec('Patterns', 200)) // the append
  const over = check(r2).breaches.map(b => b.file)
  const s1 = split(r2, 'docs/DESIGN.md', 4000)
  const c2 = check(r2)
  const idx = read(r2, 'docs/DESIGN.md'), ag = read(r2, 'AGENTS.md')
  let again = ''
  try { split(r2, 'docs/DESIGN.md', 4000) } catch (e) { again = e.message }      // repeat run: refuses, no change
  // grow part 02 past the limit, split it again → sub-part 02a, listed right after 02
  writeFileSync(join(r2, s1.parts[1]), read(r2, s1.parts[1]) + sec('States', 200))
  const s2 = split(r2, s1.parts[1], 4000)
  // a new section written into the index: split moves only that, appends one Parts row
  writeFileSync(join(r2, 'docs/DESIGN.md'), read(r2, 'docs/DESIGN.md') + '\n' + sec('Motion', 50))
  const s3 = split(r2, 'docs/DESIGN.md', 4000)
  const c3 = check(r2), idx3 = read(r2, 'docs/DESIGN.md')
  const order = [...idx3.matchAll(/\(design\/([^)]+)\)/g)].map(m => m[1])
  const ok2 = over.includes('docs/DESIGN.md') && s1.parts.length === 3 && c2.ok && c2.breaches.length === 0 &&
    /## Parts/.test(idx) && !/lorem/.test(idx) && c2.families[0].parts === 3 &&
    ag.includes('](docs/design/02-components.md#components)') && ag.includes('[index](docs/DESIGN.md)') &&
    read(r2, s1.parts[1]).includes('## not a heading (in a fence)') && /already split/.test(again) &&
    s2.parts.length === 1 && /^docs\/design\/02a-/.test(s2.parts[0]) && s3.parts.length === 1 && /04-motion/.test(s3.parts[0]) &&
    c3.ok && c3.breaches.length === 0 && c3.families[0].parts === 5 &&
    JSON.stringify(order) === JSON.stringify([...order].sort()) && (idx3.match(/^## Parts/gm) || []).length === 1 && !/lorem/.test(idx3)
  if (!ok2) fail('split', { over, s1, s2, s3, again, c2, c3, idx3, ag, order })

  // 4. issue 6: one run recurses to ### and below; issue 7/8: ADRs untouched, backticked refs repointed
  const [r3, w3] = fixture()
  w3('.keel/meta.json', JSON.stringify({ defaultBudget: 3000 }))
  w3('docs/ARCHITECTURE.md', '# Arch\n\n' + sec('Overview', 100) + '## Components\n\n' + sec('Gateway', 200, 3) + sec('Runner', 200, 3) + sec('Store', 200, 3) + sec('Costs', 100))
  w3('docs/adr/ADR-001-x.md', '# ADR-001\nSee [runner](../ARCHITECTURE.md#runner).\n')
  w3('AGENTS.md', 'Status: `docs/ARCHITECTURE.md#store` and [g](docs/ARCHITECTURE.md#gateway)\n')
  const adrBefore = read(r3, 'docs/adr/ADR-001-x.md')
  const s4 = split(r3, 'docs/ARCHITECTURE.md', 3000)
  const c4 = check(r3), a4 = read(r3, 'AGENTS.md'), i4 = read(r3, 'docs/ARCHITECTURE.md')
  const names = s4.parts.map(f => basename(f))
  if (!(c4.ok && c4.breaches.length === 0 && names.some(n => /^02a-/.test(n)) && names.indexOf(names.find(n => /^02a/.test(n))) < names.indexOf(names.find(n => /^03-/.test(n))) &&
    read(r3, 'docs/adr/ADR-001-x.md') === adrBefore && s4.adrSkipped >= 1 && /\| \[02a-runner\]\(architecture\/02a-runner\.md\) \| Runner \|\n\| \[02b/.test(i4) && /## Moved sections[\s\S]*`#runner`/.test(i4) &&
    /`docs\/architecture\/[^`]+#store`/.test(a4) && /\(docs\/architecture\/[^)]+#gateway\)/.test(a4))) fail('recurse/adr/backtick', { s4, c4, a4, i4 })

  // 5. issue 5: a part that is one big table (deferred items) splits by rows, header repeated; --where finds the last chunk
  const [r4, w4] = fixture()
  w4('.keel/meta.json', JSON.stringify({ defaultBudget: 3000 }))
  w4('docs/IMPLEMENTATION_PLAN.md', '# Plan\n\n## Parts\n\n| Part | Covers |\n|---|---|\n| [01-deferred-items](implementation-plan/01-deferred-items.md) | Deferred items |\n')
  w4('docs/implementation-plan/01-deferred-items.md', '# Plan — Deferred items\n> Part of [IMPLEMENTATION_PLAN.md](../IMPLEMENTATION_PLAN.md) · all parts listed there.\n\n## Deferred items\n\n| # | Item | Owner |\n|---|---|---|\n' +
    Array.from({ length: 120 }, (_, i) => `| ${i + 1} | deferred thing number ${i + 1} with some detail | eng |\n`).join(''))
  const tv = verdicts(r4)['docs/implementation-plan/01-deferred-items.md']
  const s5 = split(r4, 'docs/implementation-plan/01-deferred-items.md', 3000)
  const c5 = check(r4), last = s5.parts[s5.parts.length - 1]
  if (!(tv.verdict === 'split' && c5.ok && c5.breaches.length === 0 && s5.parts.length >= 2 &&
    s5.parts.every(f => read(r4, f).includes('| # | Item | Owner |')) && read(r4, last).includes('| 120 |') &&
    where(r4, 'docs/IMPLEMENTATION_PLAN.md', 'Deferred items') === last)) fail('rows/where', { tv, s5, c5, last })
  console.log('ok'); process.exit(0)
}

const arg = f => process.argv[process.argv.indexOf(f) + 1]
const meta = loadMeta('.')
const refuse = (doc, m) => { console.error(`${doc}: not done — ${m}`); process.exit(2) }
if (process.argv.includes('--where')) {
  const i = process.argv.indexOf('--where')
  console.log(where('.', process.argv[i + 1], process.argv[i + 2] || '')); process.exit(0)
}
if (process.argv.includes('--move-out')) {
  const i = process.argv.indexOf('--move-out'), ks = process.argv[i + 1]
  if (!KEYSTONE.has(ks)) refuse(ks, '--move-out is for AGENTS.md / CLAUDE.md; other docs use --split')
  try { console.log(`moved "${process.argv[i + 2]}" out of ${ks} → ${moveOut('.', ks, process.argv[i + 2] || '')}`) } catch (e) { refuse(ks, e.message) }
}
if (process.argv.includes('--split')) {
  const doc = arg('--split')
  const f = check('.', { afterArchive: true }).files.find(x => x.file === doc)
  if (KEYSTONE.has(doc)) refuse(doc, `keystone: archive it, then node .keel/doc-size.mjs --move-out ${doc} "<section>"; never split`)
  if (isArchive(doc, meta)) refuse(doc, 'archive: append-only history, never split')
  if (existsSync(doc) && isStub(readFileSync(doc, 'utf8'))) refuse(doc, 'redirect stub: never split')
  if (f && ['waived', 'manual'].includes(f.verdict)) refuse(doc, `${f.verdict}: ${f.reason}`)
  try {
    const r = split('.', doc, f ? f.budget : (meta.budgets || {})[doc] ?? meta.defaultBudget ?? 32768)
    console.log(`split ${doc}: ${r.parts.length} new part(s) in ${r.folder}/ — ${r.parts.join(', ')}; ${r.rewired} inbound reference(s) repointed${r.adrSkipped ? `; ${r.adrSkipped} in ADR files left as-is (listed under "Moved sections")` : ''}`)
  } catch (e) { refuse(doc, e.message) }
}
const res = check('.', { afterArchive: process.argv.includes('--after-archive') })
if (process.argv.includes('--json')) console.log(JSON.stringify(res, null, 1))
else {
  const icon = { ok: '✅', waived: '🟡', archive: '📦', split: '✂️ ', manual: '✋' }
  for (const f of res.files) console.log(`${icon[f.verdict]} ${f.verdict.padEnd(7)} ${f.file} ${f.size}/${f.budget}B${f.part ? ` (part of ${f.part})` : ''}${f.reason ? ` — ${f.reason}` : ''}`)
  for (const fam of res.families) console.log(`   ${fam.parent} + ${fam.parts} parts in ${fam.folder}/ = ${fam.total}B total`)
  for (const e of res.linkErrors) console.log(`LINK ERROR ${e}`)
}
process.exit(res.ok ? 0 : 1)
